using System;using System.IO;using System.Linq;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1StoryProvenance {public static object Run(){string root=Path.GetFullPath(Application.dataPath+"/../../..");const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";var qs=JArray.Parse(File.ReadAllText(root+"/SourceAssets/F1_EnvironmentalStory/models.json"));foreach(string file in new[]{"ivy","litter"})qs.Add(JObject.Parse(File.ReadAllText(root+"/SourceAssets/F1_EnvironmentalStory/"+file+".json")));var models=qs.Select(q=>{string name=(string)q["name"],path=E+name+".fbx";using(var hash=SHA256.Create())return new{name,path,guid=AssetDatabase.AssetPathToGUID(path),sha256=BitConverter.ToString(hash.ComputeHash(File.ReadAllBytes(path))).Replace("-","").ToLowerInvariant(),triangles=q["triangles"],materials=q["materials"]};}).ToArray();var report=new{author="송예찬",date="2026-11-13",source="Original procedural mesh authoring with Blender 5.2.2; adapted project-owned Unity URP material detail",scope="1F floor use, localized wall weathering, rooted ivy and material-specific roof fall; static art only",sourceFolder="SourceAssets/F1_EnvironmentalStory",models};string p="Assets/Afrer_Seconds/06.Data/AssetSources/1F_EnvironmentalStory_20261113.json";File.WriteAllText(p,JsonConvert.SerializeObject(report,Formatting.Indented));AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport);return new{models=models.Length,path=p};}
 public static object Ready(){var s=SceneManager.GetActiveScene();return new{scene=s.path,saved=!s.isDirty,playing=Application.isPlaying,playStart=AssetDatabase.GetAssetPath(EditorSceneManager.playModeStartScene)};}}
